interface LoadingProps {
  isLoading: boolean;
}

function withLoading<P extends LoadingProps>(
  WrappedComponent: React.ComponentType<P>
) {
  const WithLoading = (props: Omit<P, keyof LoadingProps>) => {
    const { isLoading, ...rest } = props as P;

    if (isLoading) {
      return (
        <div className="flex items-center justify-center p-8">
          <div className="h-8 w-8 animate-spin rounded-full border-4 border-accent-fg border-t-transparent" />
        </div>
      );
    }

    return <WrappedComponent {...(rest as P)} />;
  };

  WithLoading.displayName = `withLoading(${WrappedComponent.displayName ?? WrappedComponent.name ?? 'Component'})`;

  return WithLoading;
}

// Usage
function UserList({ users }: { users: string[] }) {
  return (
    <ul>
      {users.map((u) => (
        <li key={u}>{u}</li>
      ))}
    </ul>
  );
}

UserList.displayName = 'UserList';
const UserListWithLoading = withLoading(UserList);

