function withLogger<P extends object>(
  WrappedComponent: React.ComponentType<P>
) {
  const WithLogger = (props: P) => {
    console.log(
      `%c[Render]%c ${WrappedComponent.displayName ?? WrappedComponent.name ?? 'Component'}`,
      'color: #2563eb; font-weight: bold;',
      'color: inherit;',
      props
    );

    return <WrappedComponent {...props} />;
  };

  WithLogger.displayName = `withLogger(${WrappedComponent.displayName ?? WrappedComponent.name ?? 'Component'})`;

  return WithLogger;
}

