import { useState, useEffect } from 'react';

interface User {
  id: string;
  name: string;
  email: string;
}

function withUserData<P extends object>(
  WrappedComponent: React.ComponentType<P & { user?: User }>
) {
  const WithUserData = (props: P) => {
    const [user, setUser] = useState<User | null>(null);
    const [error, setError] = useState<Error | null>(null);

    useEffect(() => {
      let cancelled = false;

      fetch('/api/me')
        .then((res) => {
          if (!res.ok) throw new Error('Failed to fetch user');
          return res.json();
        })
        .then((data) => {
          if (!cancelled) setUser(data);
        })
        .catch((err) => {
          if (!cancelled) setError(err);
        });

      return () => {
        cancelled = true;
      };
    }, []);

    if (error) return <div>Error: {error.message}</div>;
    if (!user) return <div>Loading...</div>;

    return <WrappedComponent {...props} user={user} />;
  };

  WithUserData.displayName = `withUserData(${WrappedComponent.displayName ?? WrappedComponent.name ?? 'Component'})`;

  return WithUserData;
}

// Usage
function Profile({ user }: { user: User }) {
  return <div>{user.name}</div>;
}

Profile.displayName = 'Profile';
const ProfileWithUser = withUserData(Profile);
